70	/**
71	 * @author Vitaliy Fedoriv
72	 */
73	
74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
80	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
81	
82	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
83	    private static final int MAX_OWNERS_PER_CITY = 50;
84	
85	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
86	    private static final int MAX_OWNERS_PER_DAY = 100;
87	
88	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
89	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
90	
91	    /** Request header carrying the client-supplied idempotency key for a create; see {@link #addOwner}. */
92	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
93	
94	    /**
95	     * Remembers, per idempotency key, the id of the owner the first create with that key produced, so a repeated
96	     * create with an already-seen key returns the original owner instead of creating a duplicate.
97	     */
98	    private final Map<String, Integer> idempotentOwnerIds = new ConcurrentHashMap<>();
99	
100	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
101	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
102	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
103	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
104	
105	    private final ClinicService clinicService;
106	
107	    private final OwnerMapper ownerMapper;
108	
109	    private final PetMapper petMapper;
110	
111	    private final VisitMapper visitMapper;
112	
113	    private final TelephoneNormalizer telephoneNormalizer;
114	
115	    private final AddressNormalizer addressNormalizer;
116	
117	    private final EmailNormalizer emailNormalizer;
118	
119	    private final IdentityKeyResolver identityKeyResolver;
120	
121	    private final HouseholdResolver householdResolver;
122	
123	    /** The current request, used to read the optional {@code Idempotency-Key} header on a create. */
124	    private final HttpServletRequest request;
125	
126	    public OwnerRestControllerV1(ClinicService clinicService,
127	                                 OwnerMapper ownerMapper,
128	                                 PetMapper petMapper,
129	                                 VisitMapper visitMapper,
130	                                 TelephoneNormalizer telephoneNormalizer,
131	                                 AddressNormalizer addressNormalizer,
132	                                 EmailNormalizer emailNormalizer,
133	                                 IdentityKeyResolver identityKeyResolver,
134	                                 HouseholdResolver householdResolver,
135	                                 HttpServletRequest request) {
136	        this.clinicService = clinicService;
137	        this.ownerMapper = ownerMapper;
138	        this.petMapper = petMapper;
139	        this.visitMapper = visitMapper;
140	        this.telephoneNormalizer = telephoneNormalizer;
141	        this.addressNormalizer = addressNormalizer;
142	        this.emailNormalizer = emailNormalizer;
143	        this.identityKeyResolver = identityKeyResolver;
144	        this.householdResolver = householdResolver;
145	        this.request = request;
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
151	        Collection<Owner> owners;
152	        if (lastName != null) {
153	            owners = this.clinicService.findOwnerByLastName(lastName);
154	        } else {
155	            owners = this.clinicService.findAllOwners();
156	        }
157	        if (owners.isEmpty()) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        owners.forEach(this::populateHouseholdMemberCount);
161	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
162	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        populateHouseholdMemberCount(owner);
173	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
174	    }
175	
176	    /**
177	     * Maps an owner to its DTO and stamps on the two derived values the mapper cannot produce on its own, each because
178	     * it depends on more than the single owner: the {@code identityKey} (see
179	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner, and the household-capped
180	     * {@code membershipLevel} (see {@link #cappedMembershipLevel}), which the mapper derives from the owner alone but
181	     * which the ceiling rule then caps against the owner's fellow household members. The capped level replaces the
182	     * mapper's uncapped one on the returned DTO.
183	     *
184	     * @param owner the owner to map
185	     * @return the owner DTO carrying its identity key and household-capped membership level
186	     */
187	    private OwnerDto toOwnerDto(Owner owner) {
188	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
189	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
190	        ownerDto.setMembershipLevel(cappedMembershipLevel(owner));
191	        return ownerDto;
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Transactional
196	    @Override
197	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
198	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
199	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
200	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
201	            if (replay != null) {
202	                return replay;
203	            }
204	        }
205	        Owner owner = createOwner(ownerFieldsDto);
206	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
207	            idempotentOwnerIds.put(idempotencyKey, owner.getId());
208	        }
209	        return createdOwnerResponse(owner);
210	    }
211	
212	    /**
213	     * Replays the create that a previously-seen {@code Idempotency-Key} produced. When the key has already created an
214	     * owner that still exists, the original owner is returned with {@code 200 OK} instead of a duplicate being created;
215	     * otherwise (key unseen, or its owner has since been removed) {@code null} is returned and the create proceeds
216	     * normally.
217	     *
218	     * @param idempotencyKey the client-supplied idempotency key from the request header
219	     * @return a {@code 200 OK} response carrying the original owner, or {@code null} when there is nothing to replay
220	     */
221	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
222	        Integer existingId = idempotentOwnerIds.get(idempotencyKey);
223	        if (existingId == null) {
224	            return null;
225	        }
226	        Owner owner = this.clinicService.findOwnerById(existingId);
227	        if (owner == null) {
228	            return null;
229	        }
230	        populateHouseholdMemberCount(owner);
231	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
232	    }
233	
234	    /**
235	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
236	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
237	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guard then runs against those derived
238	     * fields (see {@link #requireUniqueIdentity}) before the soft-duplicate
239	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
240	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
241	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
242	     *
243	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
244	     * @return the newly created, persisted owner
245	     */
246	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
247	        normalizeAndValidate(ownerFieldsDto);
248	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
249	        populateDerivedFields(owner, ownerFieldsDto);
250	        requireUniqueIdentity(owner);
251	        flagPossibleDuplicate(owner, ownerFieldsDto);
252	        this.clinicService.saveOwner(owner);
253	        populateHouseholdMemberCount(owner);
254	        auditOwnerCreated(owner);
255	        return owner;
256	    }
257	
258	    /**
259	     * Builds the {@code 201 Created} response for a newly created owner: the owner mapped to its DTO (carrying its
260	     * identity key, see {@link #toOwnerDto}) as the body, with a {@code Location} header pointing at the new owner's
261	     * canonical URL.
262	     *
263	     * @param owner the newly created, persisted owner
264	     * @return a {@code 201 Created} response carrying the owner DTO and its {@code Location} header
265	     */
266	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
267	        OwnerDto ownerDto = toOwnerDto(owner);
268	        HttpHeaders headers = new HttpHeaders();
269	        headers.setLocation(UriComponentsBuilder.newInstance()
270	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
271	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
272	    }
273	
274	    /**
275	     * Emits the single audit line for a successfully created owner to the dedicated {@link #AUDIT} logger, recording
276	     * its id, customer code and registration date alongside the two values derived purely for the audit trail: the
277	     * membership level (see {@link MembershipLevelResolver#deriveMembershipLevel}) and the membership number, the
278	     * customer code suffixed with {@code -M} and the two-digit fiscal year of the registration date (see
279	     * {@link FiscalYearResolver#fiscalYear}).
280	     *
281	     * @param owner the newly created, persisted owner, with all its derived fields already in place
282	     */
283	    private void auditOwnerCreated(Owner owner) {
284	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
285	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
286	            MembershipLevelResolver.deriveMembershipLevel(owner),
287	            owner.getCustomerCode() + "-M" + String.format("%02d",
288	                FiscalYearResolver.fiscalYear(owner.getRegistrationDate()) % 100));
289	    }
290	
291	    /**
292	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
293	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
294	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
295	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
296	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
297	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
298	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
299	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
300	     *
301	     * @param owner          the newly mapped owner about to be saved
302	     * @param ownerFieldsDto the incoming owner payload
303	     */
304	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
305	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
306	        owner.setNamesakeCount(countNamesakes(owner));
307	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
308	        assignHouseholdId(owner);
309	    }
310	
311	    /**
312	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
313	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
314	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
315	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
316	     * that predate this create; distinct owners therefore always receive distinct customer codes.
317	     *
318	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
319	     * @return the de-duplicated customer code, unique across all existing owners
320	     */
321	    private String deriveUniqueCustomerCode(Owner owner) {
322	        String base = identityKeyResolver.deriveCustomerCode(owner);
323	        Collection<Owner> existing = this.clinicService.findAllOwners();
324	        String candidate = base;
325	        int n = 2;
326	        while (isCustomerCodeInUse(candidate, existing)) {
327	            candidate = base + "-" + n;
328	            n++;
329	        }
330	        return candidate;
331	    }
332	
333	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
334	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
335	    }
336	
337	    /**
338	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
339	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
340	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
341	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
342	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
343	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
344	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
345	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
346	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
347	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
348	     * assigned (see {@link #requireUniqueIdentity}).
349	     *
350	     * @param ownerFieldsDto the incoming owner payload, mutated in place
351	     * @throws MissingOwnerFieldsException if any required field is missing or blank
352	     */
353	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
354	        normalizeAddress(ownerFieldsDto);
355	        validateRequiredFields(ownerFieldsDto);
356	        validatePostcode(ownerFieldsDto);
357	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
358	        ownerFieldsDto.setTelephone(telephone);
359	        requireCityHasCapacity(ownerFieldsDto.getCity());
360	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
361	        ownerFieldsDto.setRegistrationDate(registrationDate);
362	        requireDailyLimitNotReached(registrationDate);
363	        normalizeEmail(ownerFieldsDto);
364	    }
365	
366	    /**
367	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
368	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
369	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
370	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
371	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
372	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
373	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
374	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
375	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
376	     *
377	     * @param ownerFieldsDto the incoming owner payload, mutated in place
378	     */
379	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
380	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
381	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
382	        if (!line1.isEmpty()) {
383	            ownerFieldsDto.setAddressLine1(line1);
384	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
385	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
386	        }
387	        else {
388	            ownerFieldsDto.setAddressLine1(null);
389	            ownerFieldsDto.setAddressLine2(null);
390	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
391	        }
392	    }
393	
394	    /**
395	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
396	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
397	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
398	     * place so the caller can map and save it directly.
399	     *
400	     * @param ownerFieldsDto the incoming owner payload, mutated in place
401	     */
402	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
403	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
404	    }
405	
406	    /**
407	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
408	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
409	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
410	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
411	     * date is rejected.
412	     *
413	     * @param ownerFieldsDto the incoming owner payload
414	     * @return the effective registration date rolled forward onto a business day
415	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
416	     */
417	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
418	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
419	        if (effective == null) {
420	            effective = LocalDate.now();
421	        }
422	        else if (effective.isAfter(LocalDate.now())) {
423	            throw new FutureRegistrationDateException(
424	                "the registration date must not be later than the current server date");
425	        }
426	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
427	            || PUBLIC_HOLIDAYS.contains(effective)) {
428	            effective = effective.plusDays(1);
429	        }
430	        return effective;
431	    }
432	
433	    /**
434	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
435	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
436	     * further owner may be created for that day.
437	     *
438	     * @param registrationDate the adjusted business-day registration date of the owner being created
439	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
440	     */
441	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
442	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
443	            throw new DailyOwnerLimitExceededException(
444	                "the maximum number of owners for today has already been reached");
445	        }
446	    }
447	
448	    /**
449	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
450	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
451	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
452	     * warning threshold) so both express the same per-day count in one place.
453	     *
454	     * @param registrationDate the adjusted business-day registration date to count owners for
455	     * @return the number of existing owners registered on that day
456	     */
457	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
458	        return this.clinicService.findAllOwners().stream()
459	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
460	            .count();
461	    }
462	
463	    /**
464	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
465	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
466	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
467	     * reflects only owners that predate it.
468	     *
469	     * @param registrationDate the adjusted business-day registration date of the owner being created
470	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
471	     */
472	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
473	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
474	    }
475	
476	    /**
477	     * Counts how many existing owners already share the given owner's first and last name, compared
478	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
479	     * create; it is zero when the owner's name is unique.
480	     *
481	     * @param owner the newly mapped owner about to be saved
482	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
483	     */
484	    private int countNamesakes(Owner owner) {
485	        String firstName = owner.getFirstName();
486	        String lastName = owner.getLastName();
487	        return (int) this.clinicService.findAllOwners().stream()
488	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
489	                && lastName.equalsIgnoreCase(existing.getLastName()))
490	            .count();
491	    }
492	
493	    /**
494	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
495	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
496	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
497	     *
498	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
499	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
500	     * flat {@code address}.
501	     *
502	     * @param ownerFieldsDto the owner payload to validate
503	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
504	     */
505	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
506	        List<String> missingFields = new ArrayList<>();
507	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
508	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
509	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
510	        requireText(missingFields, "city", ownerFieldsDto.getCity());
511	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
512	        if (!missingFields.isEmpty()) {
513	            throw new MissingOwnerFieldsException(missingFields);
514	        }
515	    }
516	
517	    private void requireText(List<String> missingFields, String fieldName, String value) {
518	        if (value == null || value.isBlank()) {
519	            missingFields.add(fieldName);
520	        }
521	    }
522	
523	    /**
524	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
525	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
526	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
527	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
528	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
529	     *
530	     * @param ownerFieldsDto the incoming owner payload
531	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
532	     */
533	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
534	        String postcode = ownerFieldsDto.getPostcode();
535	        if (postcode == null) {
536	            return;
537	        }
538	        Region region = Region.forCity(ownerFieldsDto.getCity());
539	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
540	            throw new InvalidPostcodeException(
541	                "postcode " + postcode + " is not valid for the city's region " + region.name());
542	        }
543	    }
544	
545	    /**
546	     * Rejects creating an owner whose whole derived {@code identityKey} (see
547	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
548	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
549	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
550	     * share only their household (same last name and postcode, different telephone) are not caught here: an owner may
551	     * join an existing household, its membership level being capped instead (see {@link #cappedMembershipLevel}).
552	     * Owners that have been soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs
553	     * only to a deleted owner does not block the create.
554	     *
555	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
556	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
557	     */
558	    private void requireUniqueIdentity(Owner owner) {
559	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
560	        boolean inUse = this.clinicService.findAllOwners().stream()
561	            .filter(existing -> !existing.isDeleted())
562	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
563	        if (inUse) {
564	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
565	        }
566	    }
567	
568	    /**
569	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
570	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. A declared
571	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
572	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
573	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
574	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
575	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
576	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
577	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
578	     *
579	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
580	     * @param ownerFieldsDto the incoming owner payload
581	     */
582	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
583	        owner.setPossibleDuplicate(false);
584	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
585	            return;
586	        }
587	        String postcode = owner.getPostcode();
588	        if (postcode == null || postcode.isBlank()) {
589	            return;
590	        }
591	        String lastName = owner.getLastName();
592	        String telephone = owner.getTelephone();
593	        for (Owner existing : this.clinicService.findAllOwners()) {
594	            if (lastName.equalsIgnoreCase(existing.getLastName())
595	                && postcode.equals(existing.getPostcode())
596	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
597	                owner.setPossibleDuplicate(true);
598	                owner.setPossibleDuplicateOf(existing.getId());
599	                return;
600	            }
601	        }
602	    }
603	
604	    /**
605	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
606	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
607	     *
608	     * @param city the city of the owner being created
609	     * @throws OwnerCityFullException if the city already contains 50 or more owners
610	     */
611	    private void requireCityHasCapacity(String city) {
612	        long cityOwners = this.clinicService.findAllOwners().stream()
613	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
614	            .count();
615	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
616	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
617	        }
618	    }
619	
620	    /**
621	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
622	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
623	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
624	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
625	     * such owners never match one another as a household.
626	     *
627	     * @param owner the newly mapped owner about to be saved
628	     */
629	    private void assignHouseholdId(Owner owner) {
630	        String postcode = owner.getPostcode();
631	        if (postcode == null || postcode.isBlank()) {
632	            owner.setHouseholdId(null);
633	            return;
634	        }
635	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
636	    }
637	
638	    /**
639	     * Returns an owner's household-capped membership level: the level the {@link MembershipLevelResolver} derives from
640	     * the owner (see {@link MembershipLevelResolver#deriveMembershipLevel(Owner)}), lowered where necessary so it never
641	     * exceeds one above the highest capped level among the owner's <em>existing</em> household members — the members
642	     * that predate the owner, identified as those sharing its non-null {@code householdId} with a smaller id. When the
643	     * owner has no such existing household member (it is the first in its household, or has no household at all) no cap
644	     * applies and the derived level is returned unchanged. The owner's transient household member count is populated
645	     * first (see {@link #populateHouseholdMemberCount}) so the derived level reflects the current household size.
646	     *
647	     * @param owner the owner whose capped membership level should be computed
648	     * @return the membership level, capped at one above the existing household maximum
649	     */
650	    private int cappedMembershipLevel(Owner owner) {
651	        populateHouseholdMemberCount(owner);
652	        int level = MembershipLevelResolver.deriveMembershipLevel(owner);
653	        Integer cap = householdMembershipLevelCap(owner);
654	        return cap == null ? level : Math.min(level, cap);
655	    }
656	
657	    /**
658	     * Computes the ceiling the {@link #cappedMembershipLevel level-ceiling rule} imposes on a new owner: one above the
659	     * highest capped membership level among the owner's existing household members, or {@code null} when there is none.
660	     * An existing household member is an owner sharing this owner's non-null {@code householdId} whose id is smaller (so
661	     * it predates this owner); their levels are read with {@link #cappedMembershipLevel}, so each member's own ceiling
662	     * is respected in turn. An owner with no household ({@code null} householdId), no id yet, or no existing household
663	     * member has no cap.
664	     *
665	     * @param owner the owner whose household level cap should be computed
666	     * @return one above the existing household maximum level, or {@code null} when no cap applies
667	     */
668	    private Integer householdMembershipLevelCap(Owner owner) {
669	        String householdId = owner.getHouseholdId();
670	        Integer id = owner.getId();
671	        if (householdId == null || id == null) {
672	            return null;
673	        }
674	        Integer maxLevel = null;
675	        for (Owner member : this.clinicService.findAllOwners()) {
676	            Integer memberId = member.getId();
677	            if (memberId != null && memberId < id && householdId.equals(member.getHouseholdId())) {
678	                int memberLevel = cappedMembershipLevel(member);
679	                maxLevel = (maxLevel == null) ? memberLevel : Math.max(maxLevel, memberLevel);
680	            }
681	        }
682	        return maxLevel == null ? null : maxLevel + 1;
683	    }
684	
685	    /**
686	     * Returns the owners that belong to the given owner's household: those sharing the same non-null
687	     * {@code householdId}. An owner with no household ({@code null} householdId) is a household of one and is returned on
688	     * its own. The lookup runs against {@link ClinicService#findAllOwners()} and, like the household member count it
689	     * backs (see {@link #populateHouseholdMemberCount}), does not exclude soft-deleted owners. When the owner has
690	     * already been saved it is itself among the members returned.
691	     *
692	     * @param owner the owner whose household members should be resolved
693	     * @return the members of the owner's household, never empty
694	     */
695	    private List<Owner> householdMembers(Owner owner) {
696	        String householdId = owner.getHouseholdId();
697	        if (householdId == null) {
698	            return List.of(owner);
699	        }
700	        return this.clinicService.findAllOwners().stream()
701	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
702	            .toList();
703	    }
704	
705	    /**
706	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
707	     * household (see {@link #householdMembers}), i.e. those sharing the same non-null {@code householdId} (including the
708	     * owner itself). An owner with no household is counted as a household of one.
709	     *
710	     * @param owner the owner whose household size should be resolved
711	     */
712	    private void populateHouseholdMemberCount(Owner owner) {
713	        owner.setHouseholdMemberCount(householdMembers(owner).size());
714	    }
715	
716	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
717	    @Override
718	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
719	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
720	        if (currentOwner == null) {
721	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
722	        }
723	        validatePostcode(ownerFieldsDto);
724	        currentOwner.setAddress(ownerFieldsDto.getAddress());
725	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
726	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
727	        currentOwner.setCity(ownerFieldsDto.getCity());
728	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
729	        currentOwner.setLastName(ownerFieldsDto.getLastName());
730	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
731	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
732	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
733	        this.clinicService.saveOwner(currentOwner);
734	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
735	    }
736	
737	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
738	    @Transactional
739	    @Override
740	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
741	        Owner owner = this.clinicService.findOwnerById(ownerId);
742	        if (owner == null) {
743	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
744	        }
745	        owner.setDeleted(true);
746	        this.clinicService.saveOwner(owner);
747	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
748	    }
749	
750	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
751	    @Override
752	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
753	        Owner owner = this.clinicService.findOwnerById(ownerId);
754	        if (owner == null) {
755	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
756	        }
757	        HttpHeaders headers = new HttpHeaders();
758	        Pet pet = petMapper.toPet(petFieldsDto);
759	        owner.setId(ownerId);
760	        pet.setOwner(owner);
761	        pet.getType().setName(null);
762	        this.clinicService.savePet(pet);
763	        PetDto petDto = petMapper.toPetDto(pet);
764	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
765	            .buildAndExpand(pet.getId()).toUri());
766	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
767	    }
768	
769	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
770	    @Override
771	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
772	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
773	        if (currentOwner != null) {
774	            Pet currentPet = this.clinicService.findPetById(petId);
775	            if (currentPet != null) {
776	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
777	                currentPet.setName(petFieldsDto.getName());
778	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
779	                this.clinicService.savePet(currentPet);
780	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
781	            }
782	        }
783	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
784	    }
785	
786	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
787	    @Override
788	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
789	        HttpHeaders headers = new HttpHeaders();
790	        Visit visit = visitMapper.toVisit(visitFieldsDto);
791	        Pet pet = new Pet();
792	        pet.setId(petId);
793	        visit.setPet(pet);
794	        this.clinicService.saveVisit(visit);
795	        VisitDto visitDto = visitMapper.toVisitDto(visit);
796	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
797	            .buildAndExpand(visit.getId()).toUri());
798	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
799	    }
800	
801	
802	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
803	    @Override
804	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
805	        Owner owner = this.clinicService.findOwnerById(ownerId);
806	        if (owner != null) {
807	            Pet pet = owner.getPet(petId);
808	            if (pet != null) {
809	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
810	            }
811	        }
812	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
813	    }
814	}
